    return "<" + tag + a + ">";
  });
  out = out.replace(/([\w$\])?]+)\.disableTooltip\(\)/g, (m, recv) => {
    if (/(summary|card\(\)\??)$/.test(recv)) { skipped.push(f + " :: " + m); return m; }
    readEdits++; return recv + ".hideHint()";
  });
  if (out !== src) {
    console.log((write ? "wrote " : "would change ") + path.relative(root, f));
    if (write) fs.writeFileSync(f, out);
  }
}
console.log({ tagEdits, readEdits });
console.log("kept receiver reads:", skipped);
